package com.hirain.aiagent.rag.indexer.cli;
import com.hirain.aiagent.rag.indexer.artifact.*;import com.hirain.aiagent.rag.indexer.embedding.*;import com.hirain.aiagent.rag.indexer.evaluation.*;import com.hirain.aiagent.rag.indexer.pipeline.*;import java.io.PrintStream;import java.util.Set;
/** 仅用于真实 Rerank 质量校准的只读评测入口，不改变 Bundle。 */
public final class EvaluateRerankCommand extends AbstractPipelineCommand {
 public EvaluateRerankCommand(BuildCancellationToken token){super(token);} @Override protected String commandName(){return "evaluate-rerank";} @Override protected Set<String> requiredOptions(){return Set.of("--bundle","--dataset","--report");}
 @Override protected int executePipeline(BuildExecutionContext c,PrintStream out){try{var dataset=new RetrievalEvaluationLoader().load(c.arguments().dataset());var evaluator=new OfflineHybridEvaluator(new DashScopeDocumentEmbeddingClient(),true);var metrics=evaluator.evaluate(c.arguments().bundle(),dataset);String hash=new BundleFileHasher().hash(BundleLayout.data(c.arguments().bundle())).sha256();new RetrievalEvaluationReportWriter().write(c.arguments().report(),hash,dataset,metrics,"HYBRID_RERANKED_V1");new RerankDiagnosticReportWriter().write(c.arguments().report().resolveSibling(c.arguments().report().getFileName()+".diagnostic.json"),evaluator.rerankDiagnostics());new RerankManualReviewReportWriter().write(c.arguments().report().resolveSibling(c.arguments().report().getFileName()+".manual-review.html"),c.arguments().bundle(),dataset,evaluator.rerankDiagnostics());out.println("EVALUATION_SUCCESS mode=HYBRID_RERANKED_V1 cases="+metrics.caseCount());return CliExitCode.SUCCESS.value();}catch(EmbeddingException e){throw new CliCommandException(CliExitCode.EMBEDDING_ERROR,e.getMessage());}catch(Exception e){throw new CliCommandException(CliExitCode.INDEX_BUILD_ERROR,"EVALUATION_FAILED");}}
}
